def word_break(s: str, words: list[str]) -> bool:
    """Return True if s can be segmented into a sequence of one or more
    words from words (words may be reused). The empty string returns True."""
    n = len(s)
    if n == 0:
        return True

    word_set = {w for w in words if w}
    if not word_set:
        return False

    # Only word lengths that could possibly match a substring of s matter.
    lengths = sorted({len(w) for w in word_set if len(w) <= n})

    # dp[i] is True if s[:i] can be segmented into words.
    dp = [False] * (n + 1)
    dp[0] = True

    for i in range(1, n + 1):
        for length in lengths:
            j = i - length
            if j < 0:
                break  # lengths are sorted ascending; rest are too long
            if dp[j] and s[j:i] in word_set:
                dp[i] = True
                break

    return dp[n]
```

