from itertools import groupby


def rle_encode(s: str) -> str:
    """Run-length encode s as count followed by character for each maximal run.

    Example: 'aaabcc' -> '3a1b2c'. The empty string encodes to ''.
    """
    return ''.join(
        f"{sum(1 for _ in group)}{char}"
        for char, group in groupby(s)
    )
