def eval_rpn(tokens: list[str]) -> int:
    def divide(a: int, b: int) -> int:
        """Integer division that truncates toward zero (exact for big ints)."""
        q = abs(a) // abs(b)
        return q if (a < 0) == (b < 0) else -q

    ops = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': divide,
    }

    stack: list[int] = []
    for token in tokens:
        if token in ops:
            b = stack.pop()
            a = stack.pop()
            stack.append(ops[token](a, b))
        else:
            stack.append(int(token))
    return stack.pop()
```

