def parse_csv_line(line: str) -> list[str]:
    fields: list[str] = []
    field: list[str] = []
    in_quotes = False
    i = 0
    n = len(line)

    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < n and line[i + 1] == '"':
                    field.append('"')
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            else:
                field.append(ch)
                i += 1
        else:
            if ch == '"' and not field:
                in_quotes = True
                i += 1
            elif ch == ',':
                fields.append(''.join(field))
                field = []
                i += 1
            else:
                field.append(ch)
                i += 1

    fields.append(''.join(field))
    return fields
